+import {
+    ValidationArguments,
+    ValidationOptions,
+    registerDecorator,
+    ValidatorConstraint,
+    ValidatorConstraintInterface,
+} from 'class-validator';
+
+import { overageAllowedEnum, PricingTier } from './create-dimension.dto.js';
+
+type TieredDimension = {
+    tiers?: PricingTier[] | null;
+    usageIncrement?: string;
+    usageEntitlement?: number | 'inf' | null;
+    consumptionPrice?: string | null;
+    overageAllowed?: overageAllowedEnum | null;
+};
+
+const numericString = /^(?:0|[1-9]\d*)(?:\.\d+)?$/;
+const integerString = /^(?:0|[1-9]\d*)$/;
+
+export function getTierValidationError(dimension: TieredDimension): string | undefined {
+    const { tiers } = dimension;
+    if (tiers === undefined || tiers === null) return undefined;
+    if (!Array.isArray(tiers) || tiers.length === 0) return 'tiers must contain at least one tier';
+    if (dimension.usageEntitlement !== undefined && dimension.usageEntitlement !== null) {
+        return 'tiers cannot be combined with usageEntitlement';
+    }
+    if (dimension.consumptionPrice !== undefined && dimension.consumptionPrice !== null) {
+        return 'tiers cannot be combined with consumptionPrice';
+    }
+    if (dimension.overageAllowed === overageAllowedEnum.true) {
+        return 'tiers cannot be combined with overageAllowed set to true';
+    }
+
+    const usageIncrement = Number(dimension.usageIncrement);
+    if (!Number.isFinite(usageIncrement) || usageIncrement <= 0) {
+        return 'usageIncrement must be greater than zero when tiers are set';
+    }
+
+    const positions = new Set<string>();
+    const sortedTiers = [...tiers].sort((left, right) => Number(left.tierPosition) - Number(right.tierPosition));
+    let previousUpperBound = 0;
+
+    for (let index = 0; index < sortedTiers.length; index += 1) {
+        const tier = sortedTiers[index];
+        if (!tier || !integerString.test(tier.tierPosition) || Number(tier.tierPosition) < 1) {
+            return 'tierPosition must be a positive integer string';
+        }
+        if (positions.has(tier.tierPosition)) return 'tierPosition values must be unique';
+        positions.add(tier.tierPosition);
+
+        if (tier.upperBound === 'inf') {
+            if (index !== sortedTiers.length - 1) return 'Only the final tier may have an upperBound of "inf"';
+        } else {
+            if (!numericString.test(tier.upperBound) || Number(tier.upperBound) <= previousUpperBound) {
+                return 'Tier upperBound values must be positive and increase without overlap';
+            }
+            const upperBound = Number(tier.upperBound);
+            if (upperBound % usageIncrement !== 0) return 'Tier upperBound values must align to usageIncrement';
+            previousUpperBound = upperBound;
+        }
+
+        if (index > 0 && tier.unitPrice === undefined) return 'Every tier after the first requires unitPrice';
+        if (tier.unitPrice !== undefined && (!numericString.test(tier.unitPrice) || tier.unitPrice.split('.')[1]?.length > 8)) {
+            return 'Tier unitPrice must be a non-negative numeric string with at most 8 decimal places';
+        }
+    }
+
+    return undefined;
+}
+
+@ValidatorConstraint({ name: 'ValidPricingTiers', async: false })
+export class ValidPricingTiersRule implements ValidatorConstraintInterface {
+    validate(_tiers: PricingTier[] | null | undefined, args: ValidationArguments) {
+        return getTierValidationError(args.object as TieredDimension) === undefined;
+    }
+
+    defaultMessage(args: ValidationArguments) {
+        return getTierValidationError(args.object as TieredDimension) ?? 'Invalid pricing tiers';
+    }
+}
+
+export function ValidPricingTiers(validationOptions?: ValidationOptions) {
+    return function (object: unknown, propertyName: string) {
+        registerDecorator({
+            name: 'ValidPricingTiers',
+            target: object.constructor,
+            propertyName,
+            options: validationOptions,
+            validator: ValidPricingTiersRule,
+        });
+    };
+}
